import{_ as t,c as o,o as i,am as n}from"./chunks/framework.83COwwOK.js";const h=JSON.parse('{"title":"Public Disclosure of Personal Information Collection","description":"","frontmatter":{},"headers":[],"relativePath":"en/agreement/privacy_collect.md","filePath":"en/agreement/privacy_collect.md"}'),s={name:"en/agreement/privacy_collect.md"};function r(a,e,l,c,d,p){return i(),o("div",null,e[0]||(e[0]=[n('<h1 id="public-disclosure-of-personal-information-collection" tabindex="-1">Public Disclosure of Personal Information Collection <a class="header-anchor" href="#public-disclosure-of-personal-information-collection" aria-label="Permalink to &quot;Public Disclosure of Personal Information Collection&quot;">​</a></h1><p>This page publicly discloses the personal privacy information collection items and their actual usage scenarios across Vilinko Studio&#39;s current services. It is designed to help users transparently understand how we collect and utilize your privacy-related data.</p><div class="tip custom-block"><p class="custom-block-title">Version</p><p>Last Updated: June 8, 2026</p></div><h2 id="pogget" tabindex="-1">Pogget <a class="header-anchor" href="#pogget" aria-label="Permalink to &quot;Pogget&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Permission / Data Type</th><th style="text-align:left;">Purpose of Collection &amp; Description of Use Cases</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Storage &amp; File Access</strong></td><td style="text-align:left;"><strong>1. User-Initiated Authorization:</strong> We only access files or data when you actively add them, solely to provide file selection, magnet link parsing, desktop organization, and content backup services. Your data is stored strictly on your local device and is not linked to any online services.<br><strong>2. Inter-project Interoperability Support:</strong> To enable feature synergy across our product ecosystem, the application may access interoperability data generated by other Vilinko projects when necessary.<br><strong>3. Access Limitation Commitment:</strong> Except for the aforementioned scenarios, this application will never access or read any other private files, photo albums, or third-party application data on your device.</td></tr><tr><td style="text-align:center;"><strong>Runtime Status &amp; Configuration Data</strong></td><td style="text-align:left;">To ensure the proper functioning of the application and deliver a personalized experience, the application reads and writes necessary local configurations and caches:<br>1. <strong>Application Status Tracking:</strong> Such as the first-launch flag, current version number, etc.;<br>2. <strong>UI Configuration Data:</strong> Such as interface layouts, user-defined settings, and UI states;<br>3. <strong>Performance Optimization Data:</strong> Such as temporary cache files, etc.</td></tr><tr><td style="text-align:center;"><strong>Network Connection &amp; Data Communication</strong></td><td style="text-align:left;">This application establishes network connections only in the following explicit scenarios and remains completely offline at all other times:<br>1. <strong>Version Update Checks:</strong> To fetch the latest version information;<br>2. <strong>Essential Information Services:</strong> To view official announcements, developer insights, and sponsor information;<br>3. <strong>Data Analysis Assistance:</strong> Operational data related to crashes and errors is collected to optimize product performance <em>only</em> after obtaining your explicit authorization.</td></tr><tr><td style="text-align:center;"><strong>Browser Invocation</strong></td><td style="text-align:left;">Triggers external browsers to open links such as Afdian, allowing you to view developer information or provide sponsorship support.</td></tr></tbody></table><h2 id="lightframe" tabindex="-1">LightFrame <a class="header-anchor" href="#lightframe" aria-label="Permalink to &quot;LightFrame&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Permission / Data Type</th><th style="text-align:left;">Purpose of Collection &amp; Description of Use Cases</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Storage &amp; File Access</strong></td><td style="text-align:left;"><strong>1. User-Initiated Authorization:</strong> We only access files or data when you actively add them, solely to provide file selection, content creation, desktop organization, and backup services. Your data is stored strictly on your local device and is not linked to any online services.<br><strong>2. Inter-project Interoperability Support:</strong> To enable feature synergy across our product ecosystem, the application may access interoperability data generated by other Vilinko projects when necessary.<br><strong>3. Access Limitation Commitment:</strong> Except for the aforementioned scenarios, this application will never access or read any other private files, photo albums, or third-party application data on your device.</td></tr><tr><td style="text-align:center;"><strong>Runtime Status &amp; Configuration Data</strong></td><td style="text-align:left;">To ensure the proper functioning of the application and deliver a personalized experience, the application reads and writes necessary local configurations and caches:<br>1. <strong>Application Status Tracking:</strong> Such as the first-launch flag, current version number, etc.;<br>2. <strong>UI Configuration Data:</strong> Such as interface layouts, user-defined settings, and UI states;<br>3. <strong>Performance Optimization Data:</strong> Such as temporary cache files, etc.</td></tr><tr><td style="text-align:center;"><strong>Network Connection &amp; Data Communication</strong></td><td style="text-align:left;">This application establishes network connections only in the following explicit scenarios and remains completely offline at all other times:<br>1. <strong>Version Update Checks:</strong> To fetch the latest version information;<br>2. <strong>Essential Information Services:</strong> To view official announcements, developer insights, and sponsor information;<br>3. <strong>Data Analysis Assistance:</strong> Operational data related to crashes and errors is collected to optimize product performance <em>only</em> after obtaining your explicit authorization.</td></tr><tr><td style="text-align:center;"><strong>Browser Invocation</strong></td><td style="text-align:left;">Triggers external browsers to open links such as Afdian, allowing you to view developer information or provide sponsorship support.</td></tr></tbody></table><h2 id="universe" tabindex="-1">Universe <a class="header-anchor" href="#universe" aria-label="Permalink to &quot;Universe&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Permission / Data Type</th><th style="text-align:left;">Purpose of Collection &amp; Description of Use Cases</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Network Connection &amp; Data Communication</strong></td><td style="text-align:left;">This application establishes network connections only in the following explicit scenarios and remains completely offline at all other times:<br>1. <strong>Version Update Checks:</strong> To retrieve the latest version information and download links for the program;<br>2. <strong>Data Analysis Assistance:</strong> Operational data related to crashes and errors is collected to optimize product performance <em>only</em> after obtaining your explicit authorization.</td></tr><tr><td style="text-align:center;"><strong>Browser Invocation</strong></td><td style="text-align:left;">Triggers specific external links used to update the program.</td></tr></tbody></table><h2 id="pogget-store" tabindex="-1">Pogget Store <a class="header-anchor" href="#pogget-store" aria-label="Permalink to &quot;Pogget Store&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Notice on Permission Usage</p><p>Inspiration Station is an online web service. The following permissions are acquired via the relevant permissions you grant to your web browser. If you have not granted these permissions to your browser or Inspiration Station, we will prompt you for authorization when required by essential services. Once you explicitly deny authorization, the following permissions will not take effect.<br> The Windows and Android applications of Inspiration Station downloaded from Vilinko-related websites are built and run based on Webview. Their permission management is identical to accessing the service directly via a web browser.</p></div><table tabindex="0"><thead><tr><th style="text-align:center;">Permission / Data Type</th><th style="text-align:left;">Purpose of Collection &amp; Description of Use Cases</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>User Behavior &amp; Engagement Data</strong></td><td style="text-align:left;">When you visit specific pages, download third-party components, undergo CAPTCHA/bot verification, vote, or search for specific content, your clicks, scrolls, page visits, and input behaviors are collected via the browser to prevent malicious bot access and specific cyber-attacks.</td></tr><tr><td style="text-align:center;"><strong>Specific Identifiers</strong></td><td style="text-align:left;">When you access Inspiration Station, your IP address is retrieved through the browser to analyze traffic sources and defend against malicious attacks. When you use the download feature, your UserAgent information is obtained via the browser to identify the device system type and version, ensuring a more compatible browsing experience.</td></tr><tr><td style="text-align:center;"><strong>Local Cache Access</strong></td><td style="text-align:left;">When you browse component descriptions or load dynamic content on Inspiration Station, the system requests cookies and localStorage permissions to prevent browser lagging caused by loading excessive dynamic content simultaneously.</td></tr></tbody></table><h2 id="vilinko-service-websites" tabindex="-1">Vilinko Service Websites <a class="header-anchor" href="#vilinko-service-websites" aria-label="Permalink to &quot;Vilinko Service Websites&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Websites Covered under This Disclosure</p><ul><li>docs.vilinko.com</li><li>support.vilinko.com</li><li>pogget.vilinko.com</li><li>lightframe.vilinko.com</li><li>www.vilinko.com</li><li>lfs.vilinko.com</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Notice on Permission Usage</p><p>When utilizing our online website services, the following permissions are acquired via the relevant permissions you grant to your web browser. If you have not granted these permissions to your browser or the website, we will prompt you for authorization when required by essential services. Once you explicitly deny authorization, the following permissions will not take effect.</p></div><table tabindex="0"><thead><tr><th style="text-align:center;">Permission / Data Type</th><th style="text-align:left;">Purpose of Collection &amp; Description of Use Cases</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Local Cache Access</strong></td><td style="text-align:left;">When you visit our websites and load dynamic content, the system requests cookies and localStorage permissions to prevent browser lagging caused by loading excessive dynamic content simultaneously.</td></tr><tr><td style="text-align:center;"><strong>Storage &amp; File Access</strong></td><td style="text-align:left;">When you utilize the download functions provided by certain websites, file access permissions are requested via the browser to download specific files. When you use the upload functions provided by certain websites, permissions to trigger the system file manager are requested via the browser.</td></tr></tbody></table>',16)]))}const u=t(s,[["render",r]]);export{h as __pageData,u as default};
